// Helper function to calculate the sum of even elements at odd indices
function SumEvenAtOddIndices(lst: seq<int>) : int
{
    var sum := 0;
    var length := |lst|;
    // Iterate over the indices of the list
    var i := 1; // Start from index 1 (the first odd index)
    while i < length
        decreases length - i // Decrease condition for termination
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i]; // Add to sum if the element is even
        }
        i := i + 2; // Move to the next odd index
    }
    sum // Return the computed sum
}
